MAP
    NAME "SS_MAP_AGUA_ZONAS_REDES"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
        INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_zonas_redes.log"
    DEBUG 0
    LAYER
        NAME "SS_MAP_AGUA_ZONAS"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        STATUS DEFAULT
        CONNECTIONTYPE POSTGIS
        INCLUDE 'includes/conexion.map'
        TYPE POLYGON
        DATA "geometry from (select gid,geometry,zona from zonas_redes) as tmp using unique gid using srid=32614"  
        LABELITEM "zona"
        CLASS
            NAME "Zona de Redes"
            STYLE
                OUTLINECOLOR 0 110 110
                WIDTH 4.0
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT 'arial'
                SIZE 20
                PARTIALS FALSE
                COLOR 0 110 110
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP